         LA    3,0(3)              NSCR
         LA    4,0(4)              NPART
         LA    5,0(5)              AID
         SR    14,14
         STH   14,0(3)
         STH   14,0(4)
         MVI   0(5),X'00'
         LA    14,4
         STH   14,0(2)
         L     1,X'224'            PSAAOLD: CURRENT ASCB
         L     1,X'3C'(1)          ASCBTSB: ZERO UNLESS TSO USER
         LTR   1,1
         BZ    DONE
         TCLEARQ OUTPUT
         TCLEARQ INPUT
         STFSMODE ON,INITIAL=YES
         STTMPMD ON
         L     6,=A(SCRTAB)        R6 = CURRENT SCREEN ENTRY
         L     7,=A(NSCRN)         R7 = SCREENS LEFT
SCREEN   DS    0H
         LH    14,0(3)
         LA    14,1(14)
         STH   14,0(3)
         L     1,0(6)              FULL SCREEN ADDRESS
         L     0,4(6)              ITS LENGTH
         TPUT  (1),(0),FULLSCR
         STH   15,0(2)
         LTR   15,15
         BNZ   BACK
         L     8,8(6)              PARTIAL TABLE
         L     9,12(6)             NUMBER OF PARTIALS
         LTR   9,9
         BZ    KEY
PART     DS    0H
         STIMER WAIT,BINTVL=HALFSEC
         L     1,0(8)
         L     0,4(8)
         TPUT  (1),(0),NOEDIT
         STH   15,0(2)
         LTR   15,15
         BNZ   BACK
         LH    14,0(4)
         LA    14,1(14)
         STH   14,0(4)
         LA    8,8(8)
         BCT   9,PART
KEY      DS    0H
         SR    10,10
KREAD    DS    0H
         LA    1,INBUF
         L     0,=F'256'
         TGET  (1),(0),ASIS
         STH   15,0(2)
         LTR   1,1
         BNZ   KGOT
         LA    10,1(10)
